import type { ConnectionResult } from './management-api'

export type EnvFileResult = {
  created: boolean
  added: string[]
  updated: string[]
}

export type GitignoreStatus = 'no-file' | 'ok' | 'missing-entry'

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Creates or updates a `.env` file with the given key-value pairs.
 *
 * Values are always written with single quotes to prevent variable expansion.
 * The exact format per line is `KEY='value'\n`.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): EnvFileResult {
  const keys = Object.keys(vars)

  // File does not exist yet: create it from scratch.
  if (!fs.existsSync(envPath)) {
    const content = keys.map((key) => `${key}='${vars[key]}'\n`).join('')
    fs.writeFileSync(envPath, content)
    return { created: true, added: [...keys], updated: [] }
  }

  let content = fs.readFileSync(envPath, 'utf-8')
  const added: string[] = []
  const updated: string[] = []

  for (const key of keys) {
    const line = `${key}='${vars[key]}'`
    const existingLine = new RegExp(`^${escapeRegExp(key)}=.*$`, 'm')

    if (existingLine.test(content)) {
      // Update the existing key in-place.
      content = content.replace(existingLine, line)
      updated.push(key)
    } else {
      // Append the new key, making sure it starts on its own line.
      if (content.length > 0 && !content.endsWith('\n')) {
        content += '\n'
      }
      content += `${line}\n`
      added.push(key)
    }
  }

  fs.writeFileSync(envPath, content)
  return { created: false, added, updated }
}

/**
 * Checks whether a `.gitignore` file exists in the given directory and whether
 * it includes an entry for `.env`.
 */
export function checkGitignore(dir: string): GitignoreStatus {
  const gitignorePath = path.join(dir, '.gitignore')

  if (!fs.existsSync(gitignorePath)) {
    return 'no-file'
  }

  const content = fs.readFileSync(gitignorePath, 'utf-8')
  const entries = content.split(/\r?\n/).map((line) => line.trim())

  if (entries.includes('.env') || entries.includes('/.env')) {
    return 'ok'
  }

  return 'missing-entry'
}

/**
 * Writes the connection string of the given {@link ConnectionResult} to the
 * `.env` file (as `DATABASE_URL`) in the specified directory.
 */
export function writeLocalFiles(dir: string, connection: ConnectionResult): { env: EnvFileResult } {
  const envPath = path.join(dir, '.env')
  const env = upsertEnvFile(envPath, { DATABASE_URL: connection.connectionString })
  return { env }
}

function readDatabaseUrl(dir: string): string | undefined {
  const envPath = path.join(dir, '.env')
  if (!fs.existsSync(envPath)) {
    return undefined
  }

  const content = fs.readFileSync(envPath, 'utf-8')
  const match = content.match(/^\s*DATABASE_URL\s*=\s*(.+?)\s*$/m)
  if (!match) {
    return undefined
  }

  // Strip surrounding single or double quotes, if any.
  return match[1].replace(/^['"]/, '').replace(/['"]$/, '')
}

/**
 * Returns `true` if the `.env` file in the given directory contains a
 * `DATABASE_URL` that points to a Prisma Postgres host.
 */
export function isAlreadyLinked(dir: string): boolean {
  const url = readDatabaseUrl(dir)
  if (!url) {
    return false
  }

  return url.includes('db.prisma.io') || url.includes('db-pool.prisma.io')
}

/**
 * Formats a human-readable summary about the `.env` file operation.
 */
export function formatEnvSummary(opts: { env: EnvFileResult; gitignoreStatus: GitignoreStatus }): string {
  const { env, gitignoreStatus } = opts

  let summary = env.created ? '  Created .env with connection strings' : '  Updated .env with connection strings'

  if (gitignoreStatus === 'missing-entry') {
    summary += '\n    warn Your .gitignore does not include .env — add it to avoid committing secrets'
  } else if (gitignoreStatus === 'no-file') {
    summary += '\n    warn No .gitignore found — create one and add .env to avoid committing secrets'
  }

  return summary
}
