/**
 * The typed Management API client used to talk to the Prisma Data Platform.
 */
export type ApiClient = ManagementApiClient

export type Project =
  operations['getV1Projects']['responses']['200']['content']['application/json']['data'][number]

export type Database =
  operations['getV1ProjectsByProjectIdDatabases']['responses']['200']['content']['application/json']['data'][number]

/**
 * Result returned by {@link createDevConnection}.
 */
export type ConnectionResult = {
  connectionString: string
}

/**
 * A loose shape of the error payload returned by the Management API. openapi-fetch
 * returns the parsed response body in the `error` field, which follows the shape
 * `{ error: { code, message, hint } }`.
 */
type ApiErrorPayload = {
  code?: string
  message?: string
  hint?: string
}

function extractApiError(error: unknown): ApiErrorPayload {
  if (error && typeof error === 'object') {
    // Response bodies wrap the details under an `error` key.
    const inner = (error as { error?: ApiErrorPayload }).error ?? (error as ApiErrorPayload)
    if (inner && typeof inner === 'object') {
      return inner
    }
  }
  if (typeof error === 'string') {
    return { message: error }
  }
  return {}
}

function apiErrorMessage(error: unknown, fallback: string): string {
  return extractApiError(error).message ?? fallback
}

/**
 * Removes sensitive data from an error message so it is safe to display.
 *
 * - Replaces `postgres://` and `prisma+postgres://` connection strings with `[REDACTED_URL]`.
 * - Replaces `--api-key` flag values with `--api-key [REDACTED]`.
 */
export function sanitizeErrorMessage(message: string): string {
  let sanitized = message

  // `prisma+postgres://` must be handled before `postgres://` to avoid leaving a
  // dangling `prisma+` prefix behind.
  sanitized = sanitized.replace(/prisma\+postgres:\/\/\S+/gi, '[REDACTED_URL]')
  sanitized = sanitized.replace(/postgres:\/\/\S+/gi, '[REDACTED_URL]')
  sanitized = sanitized.replace(/--api-key(?:=|\s+)\S+/g, '--api-key [REDACTED]')

  return sanitized
}

function isAuthenticationError(payload: ApiErrorPayload, status: number | undefined): boolean {
  const code = payload.code ?? ''
  return (
    code === 'authentication-failed' ||
    status === 401 ||
    status === 403 ||
    /auth|credential|unauthor/i.test(code)
  )
}

function isNotFoundError(payload: ApiErrorPayload, status: number | undefined): boolean {
  const code = payload.code ?? ''
  return code === 'not_found' || status === 404 || /not[-_]?found/i.test(code)
}

/**
 * Creates a new dev connection string for the given database.
 */
export async function createDevConnection(client: ApiClient, databaseId: string): Promise<ConnectionResult> {
  const { data, error, response } = await client.POST('/v1/databases/{databaseId}/connections', {
    params: { path: { databaseId } },
    body: { name: 'Prisma CLI' },
  })

  if (error) {
    const payload = extractApiError(error)
    const status = response?.status

    if (isAuthenticationError(payload, status)) {
      throw new Error('Invalid credentials')
    }
    if (isNotFoundError(payload, status)) {
      throw new Error(payload.message ? `Database not found: ${payload.message}` : 'Database not found')
    }
    throw new Error(payload.message ?? 'Failed to create database connection')
  }

  const connection = data?.data
  const connectionString =
    connection?.endpoints?.direct?.connectionString ??
    connection?.endpoints?.pooled?.connectionString ??
    connection?.connectionString

  if (!connectionString) {
    throw new Error('No connection string found in the Management API response')
  }

  return { connectionString }
}

/**
 * Returns the list of projects the current token has access to.
 */
export async function listProjects(client: ApiClient): Promise<Project[]> {
  const { data, error } = await client.GET('/v1/projects')

  if (error) {
    throw new Error(apiErrorMessage(error, 'Failed to list projects'))
  }

  return data?.data ?? []
}

/**
 * Returns the list of databases for the given project.
 */
export async function listDatabases(client: ApiClient, projectId: string): Promise<Database[]> {
  const { data, error } = await client.GET('/v1/projects/{projectId}/databases', {
    params: { path: { projectId } },
  })

  if (error) {
    throw new Error(apiErrorMessage(error, 'Failed to list databases'))
  }

  return data?.data ?? []
}
