} from './management-api'
import { checkGitignore, formatEnvSummary, isAlreadyLinked, writeLocalFiles } from './local-setup'

const DATABASE_ID_PREFIX = 'db_'

/**
 * Returns `true` if the caught error signals that the stored refresh token is no
 * longer valid and the user needs to re-authenticate.
 */
function isInvalidRefreshTokenError(error: unknown): boolean {
  return Boolean(
    error && typeof error === 'object' && (error as { refreshTokenInvalid?: unknown }).refreshTokenInvalid === true,
  )
}

/**
 * Detects whether the Prisma schema in the given directory declares any data models.
 */
function schemaHasDataModels(cwd: string, config: unknown): boolean {
  const candidates: string[] = []

  const configSchema = (config as { schema?: unknown } | null | undefined)?.schema
  if (typeof configSchema === 'string' && configSchema.length > 0) {
    candidates.push(path.isAbsolute(configSchema) ? configSchema : path.join(cwd, configSchema))
  }
  candidates.push(path.join(cwd, 'schema.prisma'))
  candidates.push(path.join(cwd, 'prisma', 'schema.prisma'))

  let contents = ''

  for (const candidate of candidates) {
    try {
      if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) {
        contents += `${fs.readFileSync(candidate, 'utf-8')}\n`
      }
    } catch {
      // Ignore unreadable candidates.
    }
  }

  // Also consider a multi-file schema folder (`prisma/schema/*.prisma`).
  const schemaDir = path.join(cwd, 'prisma', 'schema')
  try {
    if (fs.existsSync(schemaDir) && fs.statSync(schemaDir).isDirectory()) {
      for (const file of fs.readdirSync(schemaDir)) {
        if (file.endsWith('.prisma')) {
          contents += `${fs.readFileSync(path.join(schemaDir, file), 'utf-8')}\n`
        }
      }
    }
  } catch {
    // Ignore unreadable schema folders.
  }

  if (!contents) {
    return false
  }

  return /(^|\n)\s*model\s+[A-Za-z]/.test(contents)
}

/**
 * Links a local project to a Prisma Postgres database by writing the connection
 * string to the local environment file.
 */
export class Link {
  static new(): Link {
    return new Link()
  }

  private static help = format(`
    Link a local project to a Prisma Postgres database

    ${bold('Usage')}

      ${dim('$')} prisma postgres link [options]

    ${bold('Options')}

      -h, --help   Display this help message
       --api-key   A Prisma Postgres API key used for non-interactive linking
      --database   The ID of the database to link (must start with "${DATABASE_ID_PREFIX}")
         --force   Re-link the project even if it is already linked

    ${bold('Examples')}

      Link interactively by selecting a project and database
        ${dim('$')} prisma postgres link

      Link non-interactively using an API key and database ID
        ${dim('$')} prisma postgres link --api-key <key> --database db_xxxxxxxx
  `)

  async parse(argv: string[], config: unknown, cwd: string = process.cwd()): Promise<string | HelpError | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
      '--api-key': String,
      '--database': String,
      '--force': Boolean,
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args['--help']) {
      return this.help()
    }

    const apiKeyFlag = args['--api-key']
    const database = args['--database']
    const force = Boolean(args['--force'])
    const interactive = !apiKeyFlag && !database

    try {
      if (!interactive) {
        // Non-interactive mode requires an explicit database ID.
        if (!database) {
          return this.help('The --database option is required when using --api-key.')
        }
        if (!database.startsWith(DATABASE_ID_PREFIX)) {
          return this.help(
            `The --database value "${database}" is not a valid database ID. It must start with "${DATABASE_ID_PREFIX}".`,
          )
        }
      }

      // Skip re-linking if the project is already linked, unless forced.
      if (!force && isAlreadyLinked(cwd)) {
        return `This project is already linked to a Prisma Postgres database. Use --force to re-link it.`
      }

      const connection = interactive
        ? await this.linkInteractively()
        : await this.linkNonInteractively(apiKeyFlag, database!)

      const { env } = writeLocalFiles(cwd, connection)
      const gitignoreStatus = checkGitignore(cwd)
      const envSummary = formatEnvSummary({ env, gitignoreStatus })

      return this.successMessage({ cwd, config, envSummary })
    } catch (error) {
      if (error instanceof HelpError) {
        return error
      }
      const message = error instanceof Error ? error.message : String(error)
      return new HelpError(`\n${bold(red('!'))} ${sanitizeErrorMessage(message)}\n`)
    }
  }

  private async linkNonInteractively(apiKeyFlag: string | undefined, database: string): Promise<ConnectionResult> {
    const apiKey = apiKeyFlag ?? process.env.PRISMA_API_KEY

    if (!apiKey) {
      throw new HelpError(
        `\n${bold(red('!'))} No API key provided. Pass --api-key or set the PRISMA_API_KEY environment variable.\n`,
      )
    }

    const client = createManagementApiClient({ token: apiKey })
    return createDevConnection(client, database)
  }

  private async linkInteractively(): Promise<ConnectionResult> {
    try {
      return await this.runInteractiveFlow(createAuthenticatedManagementAPI().client)
    } catch (error) {
      // If the refresh token is no longer valid, log in again and retry once.
      if (isInvalidRefreshTokenError(error)) {
        await login({ utmMedium: 'command-postgres-link' })
        return this.runInteractiveFlow(createAuthenticatedManagementAPI().client)
      }
      throw error
    }
  }

  private async runInteractiveFlow(client: ApiClient): Promise<ConnectionResult> {
    const projects = await listProjects(client)

    if (projects.length === 0) {
      throw new HelpError(
        `\n${bold(red('!'))} No projects found. Create a project on the Prisma Data Platform first.\n`,
      )
    }

    const projectId = await select({
      message: 'Select a project:',
      choices: projects.map((project) => ({ name: project.name, value: project.id })),
    })

    const databases = await listDatabases(client, projectId)
    const readyDatabases = databases.filter((database) => database.status === 'ready')

    if (readyDatabases.length === 0) {
      throw new HelpError(`\n${bold(red('!'))} No ready databases found for the selected project.\n`)
    }

    const databaseId =
      readyDatabases.length === 1
        ? readyDatabases[0].id
        : await select({
            message: 'Select a database:',
            choices: readyDatabases.map((database) => ({ name: database.name, value: database.id })),
          })

    return createDevConnection(client, databaseId)
  }

  private successMessage(opts: { cwd: string; config: unknown; envSummary: string }):
