/**
 * A subcommand that can be dispatched to by {@link PostgresCommand}.
 */
export type PostgresSubCommand = {
  parse: (args: string[], config: unknown, cwd: string) => Promise<string | Error>
}

/**
 * Top-level `prisma postgres` command. Dispatches to registered subcommands.
 */
export class PostgresCommand {
  static new(subcommands: Record<string, PostgresSubCommand> = {}): PostgresCommand {
    return new PostgresCommand({
      link: Link.new() as PostgresSubCommand,
      ...subcommands,
    })
  }

  private constructor(private readonly subcommands: Record<string, PostgresSubCommand>) {}

  async parse(argv: string[], config: unknown, cwd: string = process.cwd()): Promise<string | Error> {
    // No subcommand or an explicit help request: display the help.
    if (argv.length === 0 || argv[0] === '--help' || argv[0] === '-h') {
      return this.help()
    }

    const [name, ...rest] = argv
    const subcommand = this.subcommands[name]

    if (!subcommand) {
      return unknownCommand(PostgresCommand.help, name)
    }

    return subcommand.parse(rest, config, cwd)
  }

  public help(): string {
    return PostgresCommand.help
  }

  private static help = format(`
    Manage your Prisma Postgres databases

    ${bold('Usage')}

      ${dim('$')} prisma postgres [command] [options]

    ${bold('Commands')}

          link   Link a local project to a Prisma Postgres database

